// Frozen, unsorted input also verifies that listing never mutates rows or the array.
const rows = Object.freeze([
  { id: 'c', tenant: 'a', createdAt: '2026-01-01', total: 3 },
  { id: 'b', tenant: 'b', createdAt: '2026-01-01', total: 4 },
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'd', tenant: 'a', createdAt: '2026-01-02', total: 5 },
  { id: 'B', tenant: 'a', createdAt: '2026-01-01', total: 2 }
].map(Object.freeze));
const paginated = new OrderHandler(new OrderRepository(rows));
let cursor;
const ids = [];
do {
  const page = paginated.list({ tenant: 'a', limit: 1, cursor });
  ids.push(...page.items.map(row => row.id));
  cursor = page.nextCursor;
} while (cursor !== null);
assert.deepEqual(ids, ['B', 'a', 'c', 'd']);
assert.deepEqual(paginated.list({ tenant: 'a', limit: 1, cursor: '2026-01-01|b' }), {
  items: [rows[0]], nextCursor: '2026-01-01|c'
});
// The boundary need not exist (or belong to the requested tenant).
assert.deepEqual(paginated.list({ tenant: 'a', limit: 100, cursor: '2026-01-01|bb' }).items,
  [rows[0], rows[3]]);
assert.deepEqual(paginated.list({ tenant: 'a', limit: 1, cursor: '2026-01-02|d' }),
  { items: [], nextCursor: null });
assert.deepEqual(paginated.list({ tenant: 'missing', limit: 1 }), { items: [], nextCursor: null });
for (const cursor of ['', '|a', 'date|', 'date', 'date|id|extra', null, 123]) {
  assert.throws(() => paginated.list({ tenant: 'a', limit: 1, cursor }), /^Error: invalid request$/);
}
for (const limit of [0, -1, 101, 1.5, NaN, Infinity, '1']) {
  assert.throws(() => paginated.list({ tenant: 'a', limit }), /^Error: invalid request$/);
}
assert.throws(() => paginated.list({ tenant: '', limit: 1 }), /^Error: invalid request$/);
